#include <omp.h>
#include <cstddef>
#include <string>
#include <vector>

size_t findLastShortBook(std::vector<Book> const& books) {
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(books.size());
    std::ptrdiff_t best = -1;

    #pragma omp parallel for default(none) shared(books, n) reduction(max: best)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        if (books[static_cast<size_t>(i)].pages < 100 && i > best) {
            best = i;
        }
    }

    // If no matching book exists, return size_t(-1).
    return (best >= 0) ? static_cast<size_t>(best) : static_cast<size_t>(-1);
}
